INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ORISHA_ROOT','Yoruba Orisha (West African root)',-800,1500),
 ('PER_ORISHA_DIASPORA','Orisha New-World Diaspora (Lucumi/Candomble)',1500,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BRANDON_SANTERIA','secondary scholarship','George Brandon, Santeria from Africa to the New World: The Dead Sell Memories (Indiana Univ. Press, 1993)','Yoruba orisha tradition and its Cuban Lucumi/Santeria diaspora, including the orisha-saint syncretism'),
 ('SRC_BASCOM_IFA','secondary scholarship','William Bascom, Ifa Divination: Communication between Gods and Men in West Africa (Indiana Univ. Press, 1969)','Yoruba religion, Orunmila/Ifa, and the orisha pantheon (public ethnographic description)')
INSERT INTO _e VALUES
 ('ENT_ORI_PANTHEON','The Orisha (Yoruba pantheon)','collective','collective','Yoruba-Orisha','divinity; cosmos; nature; human affairs','B','Collective hub for the orisha, the Yoruba divinities. Publicly attested in West African ethnography and the Lucumi/Candomble diaspora; living tradition.'),
 ('ENT_ORI_SEVEN_POWERS','Siete Potencias Africanas (Seven African Powers)','collective','collective','Yoruba-Orisha','protection; popular devotion','B','Popular Cuban-diaspora grouping of seven leading orishas invoked together; widely attested in Santeria devotional practice and material culture.'),
 ('ENT_ORI_OLODUMARE','Olodumare (Olorun)','deity','deity','Yoruba-Orisha','supreme being; creation; destiny; the sky','B','The remote Yoruba supreme being and source of ashe; not the object of a sacrificial cult himself. Publicly attested; living tradition.'),
 ('ENT_ORI_ESHU','Eshu (Elegguá)','deity','deity','Yoruba-Orisha','crossroads; messages; thresholds; trickster mediation','B','Messenger-trickster who opens and closes the way between humans and orishas; in Cuba called Eleggua. Publicly attested; living tradition.'),
 ('ENT_ORI_OBATALA','Obatalá (Oxalá)','deity','deity','Yoruba-Orisha','creation of human bodies; purity; wisdom; peace','B','Senior orisha of creation and moral order, associated with white. Brazilian Candomble: Oxala. Publicly attested; living tradition.'),
 ('ENT_ORI_OGUN','Ogun (Ogum)','deity','deity','Yoruba-Orisha','iron; war; tools; labor; technology','B','Orisha of iron, smithing, war and clearing the path. Publicly attested across West Africa and the diaspora; living tradition.'),
 ('ENT_ORI_SHANGO','Shango (Xangô)','deity','deity','Yoruba-Orisha','thunder; lightning; justice; kingship; fire','B','Thunder-king orisha, remembered as a deified Oyo ruler; lord of lightning and justice. Publicly attested; living tradition.'),
 ('ENT_ORI_OSHUN','Oshun (Oxum)','deity','deity','Yoruba-Orisha','fresh water; rivers; love; fertility; wealth; beauty','B','Orisha of the river and of love and fertility, junior wife of Shango in oral tradition. Publicly attested; living tradition.'),
 ('ENT_ORI_YEMOJA','Yemoja (Yemayá)','deity','deity','Yoruba-Orisha','motherhood; the sea; salt water; protection','B','Great mother orisha, of the Ogun river in Nigeria and of the sea in the Cuban diaspora (Yemaya). Publicly attested; living tradition.'),
 ('ENT_ORI_OYA','Oya','deity','deity','Yoruba-Orisha','wind; storms; the Niger river; the dead; transformation','B','Orisha of storms, wind and the marketplace, guardian of the cemetery gate; wife of Shango in oral tradition. Publicly attested; living tradition.'),
 ('ENT_ORI_BABALU_AYE','Babalú-Ayé (Omolu)','deity','deity','Yoruba-Orisha','smallpox; epidemic disease; healing; the earth','B','Orisha of contagious disease and its cure, treated with great respect; Brazilian Candomble: Omolu/Obaluaye. Publicly attested; living tradition.'),
 ('ENT_ORI_ORUNMILA','Orunmila (Orúnla)','deity','deity','Yoruba-Orisha','wisdom; destiny; Ifa divination; knowledge','B','Orisha of wisdom and witness to destiny, the patron of Ifa divination. Figure only; the divination corpus/odu interiors are not modeled. Publicly attested; living tradition.'),
 ('ENT_ORI_OLOKUN','Olokun','deity','deity','Yoruba-Orisha','the deep sea; the ocean depths; wealth; mystery','C','Orisha of the bottom of the sea and its hidden wealth, paired with Yemoja in oral tradition. Publicly attested; living tradition.'),
 ('ENT_ORI_IBEJI','Ibeji (the sacred twins)','deity','deity','Yoruba-Orisha','twins; childhood; fortune; doubling','C','The deified twins, honored for the special status of twins among the Yoruba. Publicly attested; living tradition.'),
 ('ENT_ORI_AGANJU','Aganju','deity','deity','Yoruba-Orisha','volcanoes; wilderness; the desert; rivers'' depths','C','Orisha of volcanic fire and the untamed wilderness, linked in oral tradition to Shango. Publicly attested; living tradition.');
