INSERT INTO _r VALUES
 ('ENT_ORI_OLODUMARE','member_of','ENT_ORI_PANTHEON','high','Olodumare is the supreme being at the head of the Yoruba orisha cosmos (Bascom).'),
 ('ENT_ORI_ESHU','member_of','ENT_ORI_PANTHEON','high','Eshu/Eleggua is a principal orisha (Brandon).'),
 ('ENT_ORI_OBATALA','member_of','ENT_ORI_PANTHEON','high','Obatala is a senior orisha (Brandon).'),
 ('ENT_ORI_OGUN','member_of','ENT_ORI_PANTHEON','high','Ogun is a principal orisha (Bascom).'),
 ('ENT_ORI_SHANGO','member_of','ENT_ORI_PANTHEON','high','Shango is a principal orisha (Brandon).'),
 ('ENT_ORI_OSHUN','member_of','ENT_ORI_PANTHEON','high','Oshun is a principal orisha (Brandon).'),
 ('ENT_ORI_YEMOJA','member_of','ENT_ORI_PANTHEON','high','Yemoja is a principal orisha (Brandon).'),
 ('ENT_ORI_OYA','member_of','ENT_ORI_PANTHEON','high','Oya is a principal orisha (Brandon).'),
 ('ENT_ORI_BABALU_AYE','member_of','ENT_ORI_PANTHEON','high','Babalu-Aye is a principal orisha (Brandon).'),
 ('ENT_ORI_ORUNMILA','member_of','ENT_ORI_PANTHEON','high','Orunmila is the orisha of Ifa wisdom (Bascom).'),
 ('ENT_ORI_OLOKUN','member_of','ENT_ORI_PANTHEON','high','Olokun is an orisha of the deep sea (Brandon).'),
 ('ENT_ORI_IBEJI','member_of','ENT_ORI_PANTHEON','high','The Ibeji twins are venerated among the orisha (Bascom).'),
 ('ENT_ORI_AGANJU','member_of','ENT_ORI_PANTHEON','medium','Aganju is counted among the orisha (Brandon).'),
 ('ENT_ORI_ESHU','member_of','ENT_ORI_SEVEN_POWERS','medium','Eleggua is one of the Siete Potencias Africanas in Cuban devotion (Brandon).'),
 ('ENT_ORI_OGUN','member_of','ENT_ORI_SEVEN_POWERS','medium','Ogun is one of the Seven African Powers (Brandon).'),
 ('ENT_ORI_SHANGO','member_of','ENT_ORI_SEVEN_POWERS','medium','Shango is one of the Seven African Powers (Brandon).'),
 ('ENT_ORI_OBATALA','member_of','ENT_ORI_SEVEN_POWERS','medium','Obatala is one of the Seven African Powers (Brandon).'),
 ('ENT_ORI_OSHUN','member_of','ENT_ORI_SEVEN_POWERS','medium','Oshun is one of the Seven African Powers (Brandon).'),
 ('ENT_ORI_YEMOJA','member_of','ENT_ORI_SEVEN_POWERS','medium','Yemaya is one of the Seven African Powers (Brandon).'),
 ('ENT_ORI_ORUNMILA','member_of','ENT_ORI_SEVEN_POWERS','medium','Orula is commonly counted among the Seven African Powers in Cuban devotion (Brandon).'),
 ('ENT_ORI_ESHU','mediates','ENT_ORI_PANTHEON','medium','Eshu carries the offerings and messages between humans and all the orishas, opening the way; he is the mediator, not the ruler, of the pantheon (Bascom).'),
 ('ENT_ORI_OSHUN','consort_of','ENT_ORI_SHANGO','medium','In Yoruba oral tradition Oshun is a wife of Shango (Brandon).'),
 ('ENT_ORI_OYA','consort_of','ENT_ORI_SHANGO','medium','In Yoruba oral tradition Oya is a wife of Shango (Brandon).'),
 ('ENT_ORI_AGANJU','sibling_of','ENT_ORI_SHANGO','low','Aganju is linked to Shango as kin in some oral traditions (Brandon).'),
 ('ENT_ORI_OLOKUN','paired_with','ENT_ORI_YEMOJA','medium','Olokun (deep sea) is paired with Yemoja (sea/motherhood) in oral tradition (Brandon).'),
 ('ENT_ORI_SHANGO','syncretized_with','ENT_CHR_BARBARA','high','In Cuban Lucumi/Santeria Shango is identified with Saint Barbara, sharing thunder/lightning imagery (Brandon).'),
 ('ENT_ORI_ESHU','syncretized_with','ENT_SAINT_ANTHONY_PADUA','high','In Santeria Eleggua is commonly identified with Saint Anthony of Padua (and the Holy Child of Atocha, not in DB) (Brandon).'),
 ('ENT_ORI_BABALU_AYE','syncretized_with','ENT_NT_LAZARUS_BETHANY','high','In Santeria Babalu-Aye is identified with Saint Lazarus (San Lazaro), patron against disease; ENT_NT_LAZARUS_BETHANY is the in-DB Lazarus target (Brandon).'),
 ('ENT_ORI_OBATALA','syncretized_with','ENT_MARY_MERCY','high','In Santeria Obatala is identified with Our Lady of Mercy (la Merced), sharing the color white (Brandon).'),
 ('ENT_ORI_OGUN','syncretized_with','ENT_SAINT_PETER','high','In Santeria Ogun is identified with Saint Peter, linked by iron keys/tools (Brandon).'),
 ('ENT_ORI_ORUNMILA','syncretized_with','ENT_SAINT_FRANCIS','high','In Santeria Orunmila/Orula is identified with Saint Francis of Assisi (Brandon).'),
 ('ENT_ORI_YEMOJA','syncretized_with','ENT_SAINT_MARY','medium','In Cuban Santeria Yemaya is identified with the Marian title Our Lady of Regla (a title not in DB); wired to Mary Theotokos as the underlying Marian devotion (Brandon).'),
 ('ENT_ORI_OSHUN','syncretized_with','ENT_SAINT_MARY','medium','In Cuban Santeria Oshun is identified with Our Lady of Charity of El Cobre, Cuba''s patroness (a title not in DB, verified absent); wired to Mary Theotokos as the underlying Marian devotion (Brandon).');
